5. export interface NavEntry {
6.   to: string;
7.   label: string;
8.   icon: ReactNode;
9.   disabled?: boolean;
10.   disabledHint?: string;
11. }
12. 
13. const NAV_ENTRIES: NavEntry[] = [
14.   { to: "/submit", label: "Submit", icon: <IconSubmit /> },
15.   { to: "/browse", label: "Browse", icon: <IconBrowse /> },
16.   { to: "/map", label: "Map", icon: <IconMap /> },
