31. /**
32.  * Responsive app shell: a fry-gold sidebar on desktop (>=1024px), a bottom
33.  * tab bar on mobile — same nav entries either way. Comptoir Championship
34.  * design language per code-apps/DESIGN.md (sticker shadows, pill nav items,
35.  * gravy-ink borders).
36.  */
37. export function NavShell({ children }: NavShellProps) {
38.   return (
39.     <div className="nav-shell">
40.       <aside className="nav-shell__sidebar" aria-label="Primary navigation">
41.         <div className="nav-shell__brand">
42.           <span className="nav-shell__brand-mark" aria-hidden="true">
43.             🍟
44.           </span>
45.           <span className="nav-shell__brand-name">Poutine League</span>
46.         </div>
47.         <nav className="nav-shell__nav-list">
48.           {NAV_ENTRIES.map((entry) => (
49.             <NavItem key={entry.to} entry={entry} />
50.           ))}
51.         </nav>
52.       </aside>
53. 
54.       <main className="nav-shell__content">{children}</main>
55. 
56.       <nav className="nav-shell__bottom-bar" aria-label="Primary navigation">
57.         {NAV_ENTRIES.map((entry) => (
58.           <NavItem key={entry.to} entry={entry} variant="bottom" />
59.         ))}
60.       </nav>
61.     </div>
62.   );
63. }
64. 
65. function NavItem({
66.   entry,
67.   variant = "sidebar",
68. }: {
69.   entry: NavEntry;
70.   variant?: "sidebar" | "bottom";
71. }) {
72.   const className = `nav-shell__item nav-shell__item--${variant}`;
73. 
74.   if (entry.disabled) {
75.     return (
76.       <span
77.         className={`${className} nav-shell__item--disabled`}
78.         title={entry.disabledHint}
79.         aria-disabled="true"
80.       >
81.         <span className="nav-shell__item-icon">{entry.icon}</span>
82.         <span className="nav-shell__item-label">{entry.label}</span>
83.         {entry.disabledHint && (
84.           <span className="nav-shell__item-badge">{entry.disabledHint}</span>
85.         )}
86.       </span>
87.     );
88.   }
89. 
90.   return (
91.     <NavLink
92.       to={entry.to}
93.       className={({ isActive }) =>
94.         `${className}${isActive ? " nav-shell__item--active" : ""}`
95.       }
96.     >
97.       <span className="nav-shell__item-icon">{entry.icon}</span>
98.       <span className="nav-shell__item-label">{entry.label}</span>
99.     </NavLink>
100.   );
101. }
