  const orgUrl = ctx.app.dataverseOrgUrl;
  if (!orgUrl) {
    throw new Error(
      'Dataverse org URL is not available from the Power Platform context (context.app.dataverseOrgUrl is undefined).',
    );
  }
  cachedOrgUrl = orgUrl;
  return orgUrl;
