/**
 * Shared Dataverse constants: entity set names, relationship names, and the
 * PoutineSubmission status option-set values. Kept in one place so the field/entity
 * names used across `src/data/*` stay consistent with the unpacked solution schema
 * under `solutions/poutineleaguecore/`.
 */

export const ENTITY_SETS = {
  poutineSubmissions: 'rpo_poutinesubmissions',
  restaurants: 'rpo_restaurants',
  tags: 'rpo_tags',
  systemUsers: 'systemusers',
} as const;

/** Schema name of the PoutineSubmission <-> Tag many-to-many relationship. */
export const SUBMISSION_TAG_RELATIONSHIP = 'rpo_PoutineSubmission_Tag';

/** rpo_status option-set values (see solutions/poutineleaguecore Entities/rpo_PoutineSubmission). */
export const SubmissionStatus = {
  Draft: 100000000,
  Submitted: 100000001,
  InReview: 100000002,
  Approved: 100000003,
  Rejected: 100000004,
} as const;

export type SubmissionStatusValue = (typeof SubmissionStatus)[keyof typeof SubmissionStatus];

export const SUBMISSION_STATUS_LABELS: Record<SubmissionStatusValue, string> = {
  [SubmissionStatus.Draft]: 'Draft',
  [SubmissionStatus.Submitted]: 'Submitted',
  [SubmissionStatus.InReview]: 'In Review',
  [SubmissionStatus.Approved]: 'Approved',
  [SubmissionStatus.Rejected]: 'Rejected',
};

/**
 * Statuses that count against the employee's active-submission cap.
 * Rejected submissions are excluded so a rejection frees up a slot.
 */
export const ACTIVE_SUBMISSION_STATUSES: SubmissionStatusValue[] = [
  SubmissionStatus.Draft,
  SubmissionStatus.Submitted,
  SubmissionStatus.InReview,
  SubmissionStatus.Approved,
];

export const MAX_ACTIVE_SUBMISSIONS = 5;

/**
 * Resolves the current employee's `systemuserid` from the Power Platform SDK context.
 *
 * The code app runs as the signed-in user, so we match their Azure AD object id (or
 * fall back to their UPN/email) against the `systemusers` table to find the SystemUser
 * row that PoutineSubmission.rpo_submitterid should point at.
 */
import { getContext } from '@microsoft/power-apps/app';
import { listRows } from '../lib/dataverseClient';
import { ENTITY_SETS } from './constants';

export interface CurrentUser {
  systemUserId: string;
  fullName: string;
  userPrincipalName: string;
}

let cachedUser: CurrentUser | undefined;

function escapeODataString(value: string): string {
  return value.replace(/'/g, "''");
}

/** Resolves and caches the current employee's SystemUser row. */
export async function getCurrentUser(): Promise<CurrentUser> {
  if (cachedUser) return cachedUser;

  const ctx = await getContext();
  const { objectId, userPrincipalName, fullName } = ctx.user;

  let rows = objectId
    ? await listRows(ENTITY_SETS.systemUsers, {
        select: ['systemuserid', 'fullname', 'internalemailaddress'],
        filter: `azureactivedirectoryobjectid eq '${escapeODataString(objectId)}'`,
        top: 1,
      })
    : [];

  if (rows.length === 0 && userPrincipalName) {
    rows = await listRows(ENTITY_SETS.systemUsers, {
      select: ['systemuserid', 'fullname', 'internalemailaddress'],
      filter: `internalemailaddress eq '${escapeODataString(userPrincipalName)}'`,
      top: 1,
    });
  }

  const row = rows[0];
  if (!row) {
    throw new Error(
      `Could not find a SystemUser record matching the signed-in account (${userPrincipalName ?? objectId ?? 'unknown'}).`,
    );
  }

  cachedUser = {
    systemUserId: String(row.systemuserid),
    fullName: (row.fullname as string | undefined) ?? fullName ?? 'You',
    userPrincipalName: userPrincipalName ?? '',
  };
  return cachedUser;
}

