/*
 * Shared form primitives (fields, buttons) reused across the Submit + My Submissions
 * screens (RestaurantPicker, TagMultiSelect, SubmissionForm, MySubmissionsList).
 * Component-specific layout stays in each component's own .css file; only the
 * cross-cutting field/button vocabulary lives here, mirroring how tokens.css is
 * the single shared source for design tokens.
 */

.form-field {
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
  margin-bottom: var(--space-md);
}

.form-field__label {
  font-family: var(--font-body);
  font-size: var(--text-label-size);
  font-weight: var(--text-label-weight);
  letter-spacing: var(--text-label-letter-spacing);
  color: var(--color-gravy-text-soft);
  text-transform: uppercase;
}

.form-field__input,
.form-field__textarea,
.form-field__select {
  font-family: var(--font-body);
  font-size: var(--text-body-size);
  color: var(--color-gravy-text);
  background-color: var(--color-paper-white);
  border: 2px solid var(--color-gravy-ink);
  border-radius: var(--radius-sm);
  padding: var(--space-sm) var(--space-md);
}

.form-field__textarea {
  resize: vertical;
  min-height: 96px;
  font-family: var(--font-body);
}

.form-field__input:disabled,
.form-field__textarea:disabled,
.form-field__select:disabled {
  background-color: var(--color-checker-light);
  color: var(--color-gravy-text-soft);
}

.form-field__hint {
  font-family: var(--font-body);
  font-size: var(--text-label-size);
  color: var(--color-gravy-text-soft);
}

.form-field__error {
  font-family: var(--font-body);
  font-size: var(--text-label-size);
  font-weight: var(--text-label-weight);
  color: var(--color-ketchup-red);
}

.form-actions {
  display: flex;
  gap: var(--space-md);
  flex-wrap: wrap;
  margin-top: var(--space-lg);
}

.btn {
  font-family: var(--font-body);
  font-size: var(--text-title-size);
  font-weight: var(--text-title-weight);
  border-radius: var(--radius-pill);
  border: 2px solid var(--color-gravy-ink);
  padding: 12px 28px;
  box-shadow: var(--shadow-sticker);
  transition: box-shadow 0.1s ease, transform 0.1s ease;
}

.btn:hover:not(:disabled) {
  box-shadow: var(--shadow-sticker-lifted);
}

.btn:active:not(:disabled) {
  box-shadow: var(--shadow-sticker-pressed);
}

.btn:disabled {
  opacity: 0.55;
  box-shadow: none;
  cursor: not-allowed;
}

.btn--primary {
  background-color: var(--color-fry-gold);
  color: var(--color-gravy-ink);
}

.btn--primary:hover:not(:disabled) {
  background-color: var(--color-fry-gold-deep);
}

.btn--secondary {
  background-color: var(--color-paper-white);
  color: var(--color-gravy-ink);
}

.btn--destructive {
  background-color: var(--color-ketchup-red);
  color: var(--color-paper-white);
}

.btn--destructive:hover:not(:disabled) {
  background-color: var(--color-ketchup-red-deep);
}

.btn--small {
  font-size: var(--text-body-size);
  padding: 8px 20px;
}

.restaurant-picker {
  position: relative;
}

.restaurant-picker__selected {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-sm);
  background-color: var(--color-checker-light);
  border: 2px solid var(--color-gravy-ink);
  border-radius: var(--radius-sm);
  padding: var(--space-sm) var(--space-md);
}

.restaurant-picker__selected-name {
  font-family: var(--font-body);
  font-weight: 700;
  color: var(--color-gravy-text);
}

.restaurant-picker__change {
  background: none;
  border: none;
  font-family: var(--font-body);
  font-size: var(--text-label-size);
  font-weight: var(--text-label-weight);
  color: var(--color-ketchup-red);
  text-decoration: underline;
  padding: 0;
}

.restaurant-picker__results {
  position: relative;
  margin-top: var(--space-xs);
  background-color: var(--color-paper-white);
  border: 2px solid var(--color-gravy-ink);
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-sticker);
  overflow: hidden;
}

.restaurant-picker__hint {
  padding: var(--space-sm) var(--space-md);
  font-size: var(--text-label-size);
  color: var(--color-gravy-text-soft);
}

.restaurant-picker__result {
  display: flex;
  flex-direction: column;
  width: 100%;
  text-align: left;
  background: none;
  border: none;
  border-bottom: 1px solid var(--color-checker-light);
  padding: var(--space-sm) var(--space-md);
}

.restaurant-picker__result:last-child {
  border-bottom: none;
}

.restaurant-picker__result:hover {
  background-color: var(--color-cream-counter);
}

.restaurant-picker__result-name {
  font-family: var(--font-body);
  font-weight: 700;
  color: var(--color-gravy-text);
}

.restaurant-picker__result-address {
  font-size: var(--text-label-size);
  color: var(--color-gravy-text-soft);
}

import type { TagRow } from '../../data/tags';
import './TagMultiSelect.css';

interface TagMultiSelectProps {
  tags: TagRow[];
  selectedTagIds: string[];
  onChange: (tagIds: string[]) => void;
  disabled?: boolean;
}

/** Chip-style multi-select for the seeded Tag table (DESIGN.md `chip-tag` component). */
export function TagMultiSelect({ tags, selectedTagIds, onChange, disabled }: TagMultiSelectProps) {
  function toggle(tagId: string) {
    if (selectedTagIds.includes(tagId)) {
      onChange(selectedTagIds.filter((id) => id !== tagId));
    } else {
      onChange([...selectedTagIds, tagId]);
    }
  }

  if (tags.length === 0) {
    return <p className="form-field__hint">No tags are available yet.</p>;
  }

  return (
    <div className="tag-multi-select" role="group" aria-label="Tags">
      {tags.map((tag) => {
        const isSelected = selectedTagIds.includes(tag.rpo_tagid);
        return (
          <button
            type="button"
            key={tag.rpo_tagid}
            className={`tag-chip${isSelected ? ' tag-chip--selected' : ''}`}
            aria-pressed={isSelected}
            disabled={disabled}
            onClick={() => toggle(tag.rpo_tagid)}
          >
            {tag.rpo_name}
          </button>
        );
      })}
    </div>
  );
}

.tag-multi-select {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
}

.tag-chip {
  font-family: var(--font-body);
  font-size: var(--text-label-size);
  font-weight: var(--text-label-weight);
  letter-spacing: var(--text-label-letter-spacing);
  background-color: var(--color-checker-light);
  color: var(--color-gravy-text);
  border: 2px solid transparent;
  border-radius: var(--radius-pill);
  padding: 4px 12px;
}

.tag-chip--selected {
  background-color: var(--color-fry-gold);
  border-color: var(--color-gravy-ink);
  color: var(--color-gravy-ink);
}

.tag-chip:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

import { SUBMISSION_STATUS_LABELS, SubmissionStatus, type SubmissionStatusValue } from '../../data/constants';
import './StatusBadge.css';

interface StatusBadgeProps {
  status: SubmissionStatusValue;
}

const STATUS_MODIFIER: Record<SubmissionStatusValue, string> = {
  [SubmissionStatus.Draft]: 'draft',
  [SubmissionStatus.Submitted]: 'submitted',
  [SubmissionStatus.InReview]: 'in-review',
  [SubmissionStatus.Approved]: 'approved',
  [SubmissionStatus.Rejected]: 'rejected',
};

/** Status chip per DESIGN.md: color communicates meaning, always paired with a text label. */
export function StatusBadge({ status }: StatusBadgeProps) {
  return <span className={`status-badge status-badge--${STATUS_MODIFIER[status]}`}>{SUBMISSION_STATUS_LABELS[status]}</span>;
}

.status-badge {
  display: inline-block;
  font-family: var(--font-body);
  font-size: var(--text-label-size);
  font-weight: var(--text-label-weight);
  letter-spacing: var(--text-label-letter-spacing);
  text-transform: uppercase;
  border-radius: var(--radius-pill);
  padding: 4px 12px;
}

.status-badge--draft {
  background-color: var(--color-checker-light);
  color: var(--color-gravy-text);
}

.status-badge--submitted {
  background-color: var(--color-fry-gold);
  color: var(--color-gravy-ink);
}

.status-badge--in-review {
  background-color: var(--color-mustard-amber);
  color: var(--color-gravy-ink);
}

.status-badge--approved {
  background-color: var(--color-relish-green);
  color: var(--color-paper-white);
}

.status-badge--rejected {
  background-color: var(--color-ketchup-red);
  color: var(--color-paper-white);
}

import { useState, type FormEvent } from 'react';
import { RestaurantPicker, type RestaurantSelection } from '../RestaurantPicker/RestaurantPicker';
import { TagMultiSelect } from '../TagMultiSelect/TagMultiSelect';
import { SubmissionStatus, type SubmissionStatusValue } from '../../data/constants';
import type { TagRow } from '../../data/tags';
import './SubmissionForm.css';

export interface SubmissionFormValues {
  restaurant: RestaurantSelection;
  name: string;
  description: string;
  price: number | null;
  tagIds: string[];
  photo?: File;
}

interface SubmissionFormProps {
  tags: TagRow[];
  initialValues?: SubmissionFormValues;
  /** Draft-only actions disable the "Submit" button in edit mode after a submission has moved past Draft. */
  allowedStatuses?: SubmissionStatusValue[];
  onSave: (values: SubmissionFormValues, status: SubmissionStatusValue) => Promise<void>;
  onCancel?: () => void;
  /** When true (create mode, cap already reached), the whole form is disabled. */
  capReached?: boolean;
}

const EMPTY_VALUES: SubmissionFormValues = {
  restaurant: { name: '', address: '' },
  name: '',
  description: '',
  price: null,
  tagIds: [],
};

/**
 * Shared form for creating a new poutine submission and editing an existing Draft.
 * "Save Draft" persists with status=Draft; "Submit" persists with status=Submitted —
 * there is no moderation step in this phase, so Submitted rows simply wait for a
 * later review flow.
 */
export function SubmissionForm({ tags, initialValues, allowedStatuses, onSave, onCancel, capReached }: SubmissionFormProps) {
  const [values, setValues] = useState<SubmissionFormValues>(initialValues ?? EMPTY_VALUES);
  const [error, setError] = useState<string | null>(null);
  const [savingStatus, setSavingStatus] = useState<SubmissionStatusValue | null>(null);

  const canSubmit = allowedStatuses ? allowedStatuses.includes(SubmissionStatus.Submitted) : true;
  const isBusy = savingStatus !== null;
  const isDisabled = capReached || isBusy;

  function validate(): string | null {
    if (!values.restaurant.existingRestaurantId && (!values.restaurant.name.trim() || !values.restaurant.address.trim())) {
      return 'Enter a restaurant name and address, or pick an existing restaurant.';
    }
    if (!values.name.trim()) return 'Give your poutine a name.';
    if (values.price !== null && values.price < 0) return 'Price can\u2019t be negative.';
    return null;
  }

  async function handleSave(status: SubmissionStatusValue, e?: FormEvent) {
    e?.preventDefault();
    const validationError = validate();
    if (validationError) {
      setError(validationError);
      return;
    }
    setError(null);
    setSavingStatus(status);
    try {
      await onSave(values, status);
      if (!initialValues) setValues(EMPTY_VALUES); // reset after a successful create
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Something went wrong saving your submission.');
    } finally {
      setSavingStatus(null);
    }
  }

  return (
    <form className="submission-form" onSubmit={(e) => handleSave(SubmissionStatus.Draft, e)}>
      {capReached && (
        <p className="form-field__error" role="alert">
          You already have 5 active submissions. Withdraw a draft, or wait for a decision, before adding another.
        </p>
      )}

      <RestaurantPicker
        value={values.restaurant}
        onChange={(restaurant) => setValues((v) => ({ ...v, restaurant }))}
        disabled={isDisabled}
      />

      <label className="form-field">
        <span className="form-field__label">Poutine name</span>
        <input
          type="text"
          className="form-field__input"
          value={values.name}
          placeholder="e.g. The Late Shift Special"
          disabled={isDisabled}
          onChange={(e) => setValues((v) => ({ ...v, name: e.target.value }))}
          required
        />
      </label>

      <label className="form-field">
        <span className="form-field__label">Description</span>
        <textarea
          className="form-field__textarea"
          value={values.description}
          placeholder="What makes it worth the trip?"
          disabled={isDisabled}
          onChange={(e) => setValues((v) => ({ ...v, description: e.target.value }))}
        />
      </label>

      <label className="form-field">
        <span className="form-field__label">Price ($)</span>
        <input
          type="number"
          className="form-field__input"
          min={0}
          step={0.01}
          value={values.price ?? ''}
          disabled={isDisabled}
          onChange={(e) => setValues((v) => ({ ...v, price: e.target.value === '' ? null : Number(e.target.value) }))}
        />
      </label>

      <label className="form-field">
        <span className="form-field__label">Photo</span>
        <input
          type="file"
          accept="image/*"
          className="form-field__input"
          disabled={isDisabled}
          onChange={(e) => setValues((v) => ({ ...v, photo: e.target.files?.[0] }))}
        />
        <span className="form-field__hint">Optional — you can also add one later.</span>
      </label>

      <label className="form-field">
        <span className="form-field__label">Tags</span>
        <TagMultiSelect
          tags={tags}
          selectedTagIds={values.tagIds}
          onChange={(tagIds) => setValues((v) => ({ ...v, tagIds }))}
          disabled={isDisabled}
        />
      </label>

      {error && <p className="form-field__error" role="alert">{error}</p>}

      <div className="form-actions">
        <button type="submit" className="btn btn--secondary" disabled={isDisabled}>
          {savingStatus === SubmissionStatus.Draft ? 'Saving…' : 'Save Draft'}
        </button>
        {canSubmit && (
          <button type="button" className="btn btn--primary" disabled={isDisabled} onClick={() => handleSave(SubmissionStatus.Submitted)}>
            {savingStatus === SubmissionStatus.Submitted ? 'Submitting…' : 'Submit'}
          </button>
        )}
        {onCancel && (
          <button type="button" className="btn btn--secondary" disabled={isBusy} onClick={onCancel}>
            Cancel
          </button>
        )}
      </div>
    </form>
  );
}

